// ═══ BASIC PHASER: 3 parties, multiple phases ═══
Phaser phaser = new Phaser(3);  // 3 initial parties

// Each party:
for (int i = 0; i < 3; i++) {
    new Thread(() -> {
        phase1Work();
        phaser.arriveAndAwaitAdvance();  // sync at phase 0→1!
        phase2Work();
        phaser.arriveAndAwaitAdvance();  // sync at phase 1→2!
        phase3Work();
        phaser.arriveAndDeregister();     // done! Deregister!
    }).start();
}

// ═══ DYNAMIC REGISTRATION ═══
Phaser phaser2 = new Phaser(1);  // 1 party (main)
// Later: new worker joins!
phaser2.register();  // now 2 parties!
new Thread(() -> {
    doWork();
    phaser2.arriveAndDeregister();  // done, leave!
}).start();
phaser2.arriveAndAwaitAdvance();  // main waits for all

// ═══ onAdvance CALLBACK — runs between phases ═══
Phaser phaser3 = new Phaser(3) {
    @Override
    protected boolean onAdvance(int phase, int registeredParties) {
        System.out.println("Phase " + phase + " complete! Parties: " + registeredParties);
        return registeredParties == 0;  // terminate when no parties left!
    }
};

// ═══ COMPARISON ═══
// Feature              CountDownLatch    CyclicBarrier    Phaser
// Parties fixed?       YES (at creation) YES (at creation) NO (dynamic!)
// Reusable?            NO (one-time)     YES (auto-reset)  YES (auto-advance)
// Phases               1 (count to 0)    multiple (trips)  multiple (auto-number)
// Dynamic join/leave?  NO                NO                YES!
// Callback?            NO                YES (barrier action) YES (onAdvance)
// Terminate?           count=0           reset()           onAdvance returns true
