package com.bank.phaser;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class PhaserTest {

    // ═══ Multiple phases with fixed parties ═══
    @Test
    void multiplePhases_fixedParties() throws InterruptedException {
        Phaser phaser = new Phaser(3);
        AtomicInteger phase0Done = new AtomicInteger(0);
        AtomicInteger phase1Done = new AtomicInteger(0);
        CountDownLatch allDone = new CountDownLatch(3);

        for (int i = 0; i < 3; i++) {
            new Thread(() -> {
                phase0Done.incrementAndGet();
                phaser.arriveAndAwaitAdvance();  // phase 0→1
                assertThat(phase0Done.get()).isEqualTo(3);  // all done!

                phase1Done.incrementAndGet();
                phaser.arriveAndAwaitAdvance();  // phase 1→2
                assertThat(phase1Done.get()).isEqualTo(3);

                phaser.arriveAndDeregister();
                allDone.countDown();
            }).start();
        }
        allDone.await(10, TimeUnit.SECONDS);
        assertThat(phaser.isTerminated()).isTrue();
    }

    // ═══ Dynamic registration: parties join/leave ═══
    @Test
    void dynamicRegistration() throws InterruptedException {
        Phaser phaser = new Phaser(1);  // main = 1 party
        assertThat(phaser.getRegisteredParties()).isEqualTo(1);

        phaser.register();  // add worker! Now 2.
        assertThat(phaser.getRegisteredParties()).isEqualTo(2);

        CountDownLatch done = new CountDownLatch(1);
        new Thread(() -> {
            phaser.arriveAndDeregister();  // worker done, leaves!
            done.countDown();
        }).start();

        phaser.arriveAndAwaitAdvance();  // main waits
        done.await();
        assertThat(phaser.getRegisteredParties()).isEqualTo(0);  // worker left!
    }

    // ═══ onAdvance callback ═══
    @Test
    void onAdvance_callback() throws InterruptedException {
        AtomicInteger phaseCount = new AtomicInteger(0);
        Phaser phaser = new Phaser(2) {
            @Override protected boolean onAdvance(int phase, int parties) {
                phaseCount.incrementAndGet();
                return phase >= 2;  // terminate after phase 2!
            }
        };

        CountDownLatch done = new CountDownLatch(2);
        for (int i = 0; i < 2; i++) {
            new Thread(() -> {
                phaser.arriveAndAwaitAdvance();  // phase 0→1
                phaser.arriveAndAwaitAdvance();  // phase 1→2
                phaser.arriveAndAwaitAdvance();  // phase 2→terminate!
                done.countDown();
            }).start();
        }
        done.await(10, TimeUnit.SECONDS);
        assertThat(phaseCount.get()).isEqualTo(3);  // onAdvance called 3 times!
        assertThat(phaser.isTerminated()).isTrue();
    }

    // ═══ Variable workers per phase (ETL pipeline) ═══
    @Test
    void variableWorkersPerPhase() throws InterruptedException {
        Phaser phaser = new Phaser(5);  // 5 workers for phase 1
        AtomicInteger workersInPhase2 = new AtomicInteger(0);
        CountDownLatch allDone = new CountDownLatch(5);

        for (int i = 0; i < 5; i++) {
            final int workerId = i;
            new Thread(() -> {
                // Phase 1: all 5 participate
                phaser.arriveAndAwaitAdvance();

                if (workerId < 3) {
                    // Workers 0-2: continue to phase 2
                    workersInPhase2.incrementAndGet();
                    phaser.arriveAndAwaitAdvance();
                    phaser.arriveAndDeregister();
                } else {
                    // Workers 3-4: leave after phase 1!
                    phaser.arriveAndDeregister();
                }
                allDone.countDown();
            }).start();
        }
        allDone.await(10, TimeUnit.SECONDS);
        assertThat(workersInPhase2.get()).isEqualTo(3);  // only 3 in phase 2!
    }
}
